对比朴素采样和重参数化采样，关键差别就在梯度能不能回传：

```python
import torch
import torch.nn as nn
class GaussianSampler(nn.Module):
    def __init__(self):
        super().__init__()
        self.mu = nn.Parameter(torch.tensor(0.0))
        self.log_sigma = nn.Parameter(torch.tensor(0.0))
    @property
    def sigma(self):
        return torch.exp(self.log_sigma)
    def sample_naive(self, n):
        return torch.normal(self.mu.detach(), self.sigma.detach(), size=(n,))
    def sample_reparam(self, n):
        eps = torch.randn(n)
        return self.mu + self.sigma * eps
```

正向过程直接从 $q(x_t|x_0)$ 一步采样，不必循环；KL 对标准正态有现成闭合式：

```python
import torch
class GaussianMarkovChain:
    def __init__(self, alpha, T):
        self.alpha = alpha
        self.T = T
        self.alpha_bar = torch.tensor([alpha**t for t in range(T+1)])
    def q_sample(self, x0, t):
        ab = self.alpha_bar[t]
        eps = torch.randn_like(x0)
        return torch.sqrt(ab) * x0 + torch.sqrt(1 - ab) * eps
    def snr(self, t):
        ab = self.alpha_bar[t].item()
        return ab / (1 - ab) if ab < 1 else float('inf')
def kl_to_standard_normal(mu, sigma):
    return 0.5 * (mu**2 + sigma**2 - 2*torch.log(sigma) - 1).sum()
```
